import{bQ as n,aL as s,u as o,G as a}from"./chunks/framework.D06dwy5q.js";const h=JSON.parse('{"title":"第 08 篇｜建立排错直觉：看着一堆红字报错，怎么知道是谁的锅？","description":"","frontmatter":{},"headers":[],"relativePath":"AI-Native 普通人零代码实战指南/第 08 篇｜建立排错直觉：看着一堆红字报错，怎么知道是谁的锅？.md","filePath":"AI-Native 普通人零代码实战指南/第 08 篇｜建立排错直觉：看着一堆红字报错，怎么知道是谁的锅？.md","lastUpdated":null}'),r={name:"AI-Native 普通人零代码实战指南/第 08 篇｜建立排错直觉：看着一堆红字报错，怎么知道是谁的锅？.md"};function t(l,e,p,i,d,c){return s(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="第-08-篇-建立排错直觉-看着一堆红字报错-怎么知道是谁的锅" tabindex="-1">第 08 篇｜建立排错直觉：看着一堆红字报错，怎么知道是谁的锅？ <a class="header-anchor" href="#第-08-篇-建立排错直觉-看着一堆红字报错-怎么知道是谁的锅" aria-label="Permalink to &quot;第 08 篇｜建立排错直觉：看着一堆红字报错，怎么知道是谁的锅？&quot;">​</a></h1><blockquote><p><strong>导读</strong>：<br> 所有初学者的噩梦时刻，莫过于点击一个按钮，页面突然“白屏”或者“毫无反应”。<br> 颤颤巍巍打开控制台，屏幕上炸开一整屏猩红色的英文报错，密密麻麻几十行。新手往往瞬间心跳加速：“完了，项目彻底报废了。”<br> 别慌！<strong>在程序员眼里，红字报错不是病危通知书，而是系统给你的“破案线索”。</strong><br> 这一篇，我们教你用两招把现代浏览器变成你的“核磁共振仪”，听懂系统的呼救声，用最地道的姿势把错误投喂给 AI，一轮对话就命中问题。</p></blockquote><hr><h3 id="一、-程序员的听诊器-按一下-f12-打开新世界" tabindex="-1">一、 程序员的听诊器：按一下 <code>F12</code> 打开新世界 <a class="header-anchor" href="#一、-程序员的听诊器-按一下-f12-打开新世界" aria-label="Permalink to &quot;一、 程序员的听诊器：按一下 \`F12\` 打开新世界&quot;">​</a></h3><p>当你的网页出现异常，直接对着屏幕发呆没有任何意义。因为所有的蛛丝马迹，都被浏览器悄悄记录在后台。</p><p>在任何网页上，按下键盘上的 <strong><code>F12</code></strong>（Mac 电脑按 <code>Command + Option + I</code>，或者在页面空白处点右键 ➔ <strong>“检查” / Inspect</strong>），你就会唤出整个互联网最重要的调试工具——<strong>开发者工具（DevTools）</strong>。</p><p>开发者工具里有花里胡哨的一堆标签页，不要被吓退。<strong>作为总指挥，你终生只需要紧盯其中两个窗口</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                    ┌───────────────────────────────────┐</span></span>
<span class="line"><span>                    │       浏览器开发者工具 (F12)         │</span></span>
<span class="line"><span>                    └─────────────────┬─────────────────┘</span></span>
<span class="line"><span>                                      │</span></span>
<span class="line"><span>              ┌───────────────────────┴───────────────────────┐</span></span>
<span class="line"><span>              ▼                                               ▼</span></span>
<span class="line"><span>     【Console（控制台）】                           【Network（网络）】</span></span>
<span class="line"><span>     负责：看前端的“内部神经中风”                   负责：看前后端传菜的“物流纠纷”</span></span>
<span class="line"><span>     特征：页面逻辑崩了、代码打错字、变量找不着     特征：接口报红、数据拉不回来、跨域拦截</span></span></code></pre></div><hr><h3 id="二、-前端内部中风-console-控制台-里的典型死相" tabindex="-1">二、 前端内部中风：Console（控制台）里的典型死相 <a class="header-anchor" href="#二、-前端内部中风-console-控制台-里的典型死相" aria-label="Permalink to &quot;二、 前端内部中风：Console（控制台）里的典型死相&quot;">​</a></h3><p>如果你的页面<strong>完全白屏</strong>，或者<strong>点按钮毫无反应</strong>，第一时间切到 <strong>Console 标签页</strong>。</p><p>Console 就像前端代码的“大喇叭”。只要前端执行过程中被某一行代码噎死，它就会立刻吐出一大片红字。</p><h4 id="_1-经典绝症-typeerror-cannot-read-properties-of-undefined" tabindex="-1">1. 经典绝症：<code>TypeError: Cannot read properties of undefined</code> <a class="header-anchor" href="#_1-经典绝症-typeerror-cannot-read-properties-of-undefined" aria-label="Permalink to &quot;1. 经典绝症：\`TypeError: Cannot read properties of undefined\`&quot;">​</a></h4><ul><li><strong>人话翻译</strong>：“<em>你试图去摸一个根本不存在的人的口袋。</em>”</li><li><strong>生活场景</strong>：前端页面准备显示 <code>用户.名字</code>，结果这时候后端还没把用户资料送过来，“用户”本身是个空的空气（<code>undefined</code>），代码却急着去读取它的 <code>名字</code>，系统当场休克卡死。</li><li><strong>判定结论</strong>：纯前端逻辑顺序错误，或者没做空值容错处理。</li></ul><h4 id="_2-看懂堆栈-直击-案发第一现场" tabindex="-1">2. 看懂堆栈：直击“案发第一现场” <a class="header-anchor" href="#_2-看懂堆栈-直击-案发第一现场" aria-label="Permalink to &quot;2. 看懂堆栈：直击“案发第一现场”&quot;">​</a></h4><p>控制台红字虽然有几十行，但<strong>大部分是底层框架的连锁反应，属于废话</strong>。<br> 你的眼睛只需要看两处：</p><ol><li><strong>红字的第一行</strong>：它用最简短的英文概括了死因（比如上面提到的 <code>TypeError</code>）；</li><li><strong>红字最右侧的文件链接</strong>：比如 <code>UserCard.jsx:42</code>。这等于凶手在案发现场留下的纸条——明明白白告诉你：<strong>“我是在 UserCard 文件第 42 行暴毙的！”</strong></li></ol><hr><h3 id="三、-物流传菜纠纷-network-网络-里的典型翻车" tabindex="-1">三、 物流传菜纠纷：Network（网络）里的典型翻车 <a class="header-anchor" href="#三、-物流传菜纠纷-network-网络-里的典型翻车" aria-label="Permalink to &quot;三、 物流传菜纠纷：Network（网络）里的典型翻车&quot;">​</a></h3><p>如果页面没有白屏，Console 里也没报错，但你点“提交”，系统一直在转圈，或者弹窗提示“获取数据失败”，这时候要立刻切到 <strong>Network 标签页</strong>。</p><p>Network 记录了浏览器发出的<strong>每一次“外卖订单（请求）”</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>     Name (接口名称)      Status (状态码)     Type       Time</span></span>
<span class="line"><span>  ┌────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>  │  getUserInfo          200 (绿色/正常)    fetch      45ms │</span></span>
<span class="line"><span>  │  updateProfile        500 (红色/报错) ◄─ fetch     120ms │ ◄── 抓到凶手！</span></span>
<span class="line"><span>  └────────────────────────────────────────────────────────┘</span></span></code></pre></div><p>把界面上的状态按颜色扫一眼，只要看到<strong>红色的行</strong>，用鼠标点进去，这就是翻车现场：</p><h4 id="_1-状态码断案-复习第-05-篇" tabindex="-1">1. 状态码断案（复习第 05 篇） <a class="header-anchor" href="#_1-状态码断案-复习第-05-篇" aria-label="Permalink to &quot;1. 状态码断案（复习第 05 篇）&quot;">​</a></h4><ul><li><strong>显示 <code>404</code></strong>：请求的接口地址拼错了，门牌号不存在。</li><li><strong>显示 <code>500</code></strong>：后端云端厨房炸了。这时候<strong>不要看前端代码了</strong>，问题出在后端服务内部。</li></ul><h4 id="_2-新手头号梦魇-cors-跨域安全拦截" tabindex="-1">2. 新手头号梦魇：CORS 跨域安全拦截 <a class="header-anchor" href="#_2-新手头号梦魇-cors-跨域安全拦截" aria-label="Permalink to &quot;2. 新手头号梦魇：CORS 跨域安全拦截&quot;">​</a></h4><p>你在 Network 里经常会遇到一个看起来极其恐怖的报错：<br><code>Access to fetch at &#39;...&#39; has been blocked by CORS policy</code>。</p><p>很多新手被这一长串英文吓懵了。用大白话解释，它极其简单：</p><ul><li><strong>生活比喻</strong>：你是 A 小区的业主（你的前端运行在 <code>localhost:3000</code>），你突然伸手翻墙去掏 B 小区（运行在 <code>localhost:8000</code> 的后端）的垃圾桶。</li><li>浏览器的安保队长（CORS 机制）非常警惕，立刻冲出来按住你：“<em>住手！为了防止跨站偷窃，除非 B 小区在门口贴个告示说‘允许 A 小区访问’，否则我绝对不把数据交给你！</em>”</li><li><strong>责任方判定</strong>：<strong>代码本身没有错，纯粹是浏览器的跨域安全策略拦截了！</strong><br> 解决办法永远只有一种：<strong>去后端配置里加上“允许跨域名单”</strong>。</li></ul><hr><h3 id="四、-架构师级投喂法-让-ai-一击命中的-黄金三件套" tabindex="-1">四、 架构师级投喂法：让 AI 一击命中的“黄金三件套” <a class="header-anchor" href="#四、-架构师级投喂法-让-ai-一击命中的-黄金三件套" aria-label="Permalink to &quot;四、 架构师级投喂法：让 AI 一击命中的“黄金三件套”&quot;">​</a></h3><p>这是区别小白与高手的最关键分水岭。</p><p>看看绝大部分新手的<strong>低效提问</strong>：</p><blockquote><p>❌ <em>“AI，我的项目坏了，点击没反应，怎么办？”</em><br> ❌ <em>“页面白屏了，你刚才给我的代码有问题，重写一份！”</em></p></blockquote><p>AI 面对这种没有任何线索的指令，只能像算命先生一样瞎猜，胡乱给你改一通，结果把本来对的代码也改烂了。</p><p><strong>真正的高手，向 AI 报 Bug 永远只喂“黄金三件套”：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>【第一件：用户动作】 ──► 我刚刚在界面上做了什么具体操作</span></span>
<span class="line"><span>【第二件：案发现场】 ──► F12 控制台的具体红字 / Network 接口报错截图或复制文本</span></span>
<span class="line"><span>【第三件：预期结果】 ──► 我本来期望界面发生什么</span></span></code></pre></div><h4 id="看看这套标准的-一击必杀-prompt-模版" tabindex="-1">看看这套标准的“一击必杀” Prompt 模版： <a class="header-anchor" href="#看看这套标准的-一击必杀-prompt-模版" aria-label="Permalink to &quot;看看这套标准的“一击必杀” Prompt 模版：&quot;">​</a></h4><blockquote><p><em>“AI，我遇到了一个前端交互 Bug：</em><br><em>1. <strong>操作行为</strong>：我在个人主页点击了‘保存昵称’按钮；</em><br><em>2. <strong>控制台报错</strong>：F12 Console 抛出以下红字：</em><br><code>Uncaught TypeError: Cannot read properties of undefined (reading &#39;token&#39;) at handleSave (Profile.jsx:35)</code><br><em>同时 Network 标签页中的 <code>/api/user/update</code> 请求返回了 <code>401 Unauthorized</code>；</em><br><em>3. <strong>预期效果</strong>：期望顺利提交新昵称，并弹出‘修改成功’的绿色提示。</em><br><em>请根据上面的堆栈和状态码，精准指出问题根源并给出修复方案。”</em></p></blockquote><p>当你把这套线索甩过去：</p><ul><li>AI <strong>不需要猜</strong>是前端还是后端的问题（你已经指出了 401 和第 35 行）；</li><li>它的推理神经元会被<strong>极度收敛在最小故障面</strong>上；</li><li>大概率第一轮回复就能给出靠谱的补丁，不用来回猜。</li></ul><hr><h3 id="📝-结语与本篇自查-模块二完结" tabindex="-1">📝 结语与本篇自查（模块二完结） <a class="header-anchor" href="#📝-结语与本篇自查-模块二完结" aria-label="Permalink to &quot;📝 结语与本篇自查（模块二完结）&quot;">​</a></h3><p>恭喜你！到这里，你已经扎扎实实学完了<strong>【模块二：技术通识】</strong>的全部 4 篇内容。<br> 你不仅搞懂了互联网的运作骨架，分清了系统各部件的职责，更学会了像老手一样冷静看病。</p><p>最后做个收官自查：</p><ol><li><strong>当你点击页面上的一个按钮，页面没有跳转，但 Console 里干干净净一条红字都没有，你应该去哪里找线索？</strong><br><em>(去 Network 标签页查看是否有网络请求发出，看该请求的状态码是不是卡在挂起（Pending）或返回了错误。)</em></li><li><strong>在浏览器控制台看到 <code>blocked by CORS policy</code>，第一反应应该让 AI 去改前端样式，还是去后端添加跨域白名单？</strong><br><em>(去后端或者网关配置里添加跨域许可头，这是浏览器的跨域安全策略，前端改样式毫无意义。)</em></li><li><strong>向 AI 报告错误时，最致命的坏习惯是什么？</strong><br><em>(只说“坏了/白屏了”，不提供具体的报错日志、错误行号和复现操作步骤。)</em></li></ol><hr><p><strong>下一篇预告</strong>：<br> 认知的内功已经彻底大成，行话你也全听懂了。<br> 从下一篇起，我们将真正握紧手中的武器，正式跨入<strong>【模块三：工程实战 —— 驾驭 AI 构建专属工作流 (Harness &amp; Flow)】</strong>！<br> 在这一模块，我们将告别网页端敲代码的过家家模式，全景拆解目前最顶级的 AI 编程神器：<br> 从爆火的 <strong>Cursor、Windsurf</strong>，到前沿极客专属的<strong>终端 Agent（如 Claude Code / Aider）</strong>，告诉你普通人到底该怎么选兵器、怎么配环境！<br> 敬请期待：《<strong>第 09 篇｜AI 兵器库选型：从 Cursor、Windsurf 到桌面 Agent</strong>》！</p>`,48)])])}const u=n(r,[["render",t]]);export{h as __pageData,u as default};
